D=$(mktemp -d); echo "" | base64 -d > $D/base.py
for i in $(seq 1 50); do sudo podman exec faceops test -f /opt/faceops/app/salud_segmento_acc.py && break; sleep 30; done
sudo podman exec faceops cat /opt/faceops/app/version.json 2>/dev/null | head -c 300; echo
sudo podman exec -i -e FACEOPS_VIGIA=0 -w /opt/faceops faceops python3 - < $D/base.py 2>&1 | grep -v -i warn | grep -v "^   btn" | grep -v "TOP-HTML" | cut -c1-600 | head -24
curl -sk -o /dev/null -w "lab http %{http_code}\n" https://faceops.34.176.42.56.sslip.io:8843/faceops/ || true
